<template>
  <div class="onboard">
    <header class="topbar"><a class="brand" href="/admin/#/tournament-space"><img :src="logoSrc" alt="brand"><b>{{ t.brand }}</b></a><button class="link" type="button" @click="signOut">{{ t.logout }}</button></header>
    <main class="main"><small class="eyebrow">{{ t.eyebrow }}</small><h1>{{ t.title }}</h1><p class="lead">{{ t.lead }}</p>
      <div v-if="loading" class="card">{{ t.loading }}</div>
      <section v-else-if="reviewOnly" class="card review"><h2>{{ t.reviewTitle }}</h2><p>{{ t.reviewText }}</p><button class="primary" type="button" @click="loadState">{{ t.refresh }}</button></section>
      <template v-else><div class="choices">
        <button class="choice" :class="{active:scene==='event'}" type="button" @click="choose('event')"><em>{{ t.eventKicker }}</em><strong>{{ t.eventTitle }}</strong><span>{{ t.eventText }}</span></button>
        <button class="choice" :class="{active:scene==='training'}" type="button" @click="choose('training')"><em>{{ t.trainingKicker }}</em><strong>{{ t.trainingTitle }}</strong><span>{{ t.trainingText }}</span></button>
      </div>
      <section v-if="scene==='event'" class="card"><h2>{{ t.eventPanel }}</h2><p>{{ t.eventPanelText }}</p><form @submit.prevent="createEvent"><label>{{ t.eventName }}<input v-model.trim="eventForm.name" :placeholder="t.eventHint"></label><label>{{ t.city }}<input v-model.trim="eventForm.city" :placeholder="t.cityHint"></label><button class="primary" type="submit" :disabled="submitting">{{ submitting?t.creating:t.createEvent }}</button></form></section>
      <section v-else class="card"><h2>{{ trainingReady?t.trainingReady:t.trainingLocked }}</h2><p>{{ t.trainingPanel }}</p><label v-if="trainingReady">{{ t.orgName }}<input v-model.trim="trainingForm.name" :placeholder="t.orgHint"></label><button v-if="trainingReady" class="primary" type="button" @click="createTraining" :disabled="submitting">{{ submitting?t.creating:t.createTraining }}</button><div v-else class="locked"><b>{{ t.status }}{{ trainingStatus }}</b><p>{{ t.trainingLockedText }}</p><button class="primary" type="button" @click="loadState" :disabled="loading">{{ t.refresh }}</button><button class="ghost" type="button" @click="consult" :disabled="submitting||consulted">{{ consulted?t.consulted:t.consult }}</button></div></section></template>
    </main>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { callFunction, logout } from '../../utils/cloud'
const t = {
  brand:'\u8d5b\u5c0f\u8702\u8db3\u7403',logout:'\u9000\u51fa\u767b\u5f55',eyebrow:'\u9996\u6b21\u8fdb\u5165\u540e\u53f0',title:'\u5148\u5efa\u7acb\u4e00\u4e2a\u4e1a\u52a1\u5de5\u4f5c\u7a7a\u95f4',lead:'\u8bf7\u9009\u62e9\u4f60\u73b0\u5728\u8981\u5f00\u5c55\u7684\u4e1a\u52a1\u3002\u8fd9\u91cc\u9009\u62e9\u7684\u662f\u4e1a\u52a1\u573a\u666f\uff0c\u4e0d\u662f\u6c38\u4e45\u8eab\u4efd\uff1b\u540c\u4e00\u8d26\u53f7\u53ef\u4ee5\u5728\u540c\u4e00\u673a\u6784\u5185\u589e\u52a0\u5df2\u5f00\u901a\u7684\u80fd\u529b\u3002',
  loading:'\u6b63\u5728\u8bc6\u522b\u4f60\u7684\u673a\u6784\u5173\u7cfb\u2026',reviewTitle:'\u5df2\u6709\u4e1a\u52a1\u5173\u7cfb\uff0c\u7b49\u5f85\u673a\u6784\u4fe1\u606f\u540c\u6b65',reviewText:'\u5f53\u524d\u8d26\u53f7\u5df2\u5173\u8054\u7403\u961f\u6216\u8d5b\u4e8b\uff0c\u4f46\u6682\u65f6\u6ca1\u6709\u53ef\u7528\u7684\u673a\u6784\u5de5\u4f5c\u7a7a\u95f4\u3002\u4e3a\u907f\u514d\u8bef\u5efa\u673a\u6784\uff0c\u8bf7\u8054\u7cfb\u7ba1\u7406\u5458\u5b8c\u6210\u5f52\u5c5e\u6838\u9a8c\u3002',refresh:'\u91cd\u65b0\u68c0\u67e5',
  eventKicker:'\u53ef\u7acb\u5373\u521b\u5efa',eventTitle:'\u8d5b\u4e8b\u4e3b\u529e\u65b9',eventText:'\u521b\u5efa\u4e3b\u529e\u65b9\u5de5\u4f5c\u7a7a\u95f4\uff0c\u5e76\u540c\u6b65\u5efa\u7acb\u7b2c\u4e00\u573a\u8d5b\u4e8b\u8349\u7a3f\u3002',trainingKicker:'\u72ec\u7acb\u5f00\u901a\u80fd\u529b',trainingTitle:'\u9752\u8bad\u673a\u6784',trainingText:'\u7528\u4e8e\u8bad\u7ec3\u8425\u3001\u5b66\u5458\u548c\u6559\u7ec3\u7ecf\u8425\uff1b\u53ea\u6709\u540e\u53f0\u786e\u8ba4\u5df2\u5f00\u901a\u540e\u624d\u80fd\u521b\u5efa\u3002',
  eventPanel:'\u521b\u5efa\u4f60\u7684\u8d5b\u4e8b\u7a7a\u95f4',eventPanelText:'\u5148\u586b\u5199\u6700\u5c11\u4fe1\u606f\u5373\u53ef\u8fdb\u5165\u8d5b\u4e8b\u7a7a\u95f4\u3002',eventName:'\u9996\u573a\u8d5b\u4e8b\u540d\u79f0',eventHint:'\u4f8b\u5982\uff1a2026 \u6625\u5b63\u9752\u5c11\u5e74\u8db3\u7403\u9080\u8bf7\u8d5b',city:'\u4e3e\u529e\u57ce\u5e02',cityHint:'\u4f8b\u5982\uff1a\u90d1\u5dde',createEvent:'\u521b\u5efa\u8d5b\u4e8b\u4e3b\u529e\u65b9\u7a7a\u95f4',creating:'\u6b63\u5728\u4fdd\u5b58\u2026',
  trainingReady:'\u9752\u8bad\u80fd\u529b\u5df2\u5f00\u901a',trainingLocked:'\u9752\u8bad\u80fd\u529b\u5c1a\u672a\u5f00\u901a',trainingPanel:'\u9752\u8bad\u662f\u72ec\u7acb\u670d\u52a1\u80fd\u529b\uff0c\u5f00\u901a\u72b6\u6001\u7531\u540e\u53f0\u8d44\u683c\u51b3\u5b9a\uff0c\u9875\u9762\u4e0d\u4f1a\u7ed5\u8fc7\u8d44\u683c\u6821\u9a8c\u3002',orgName:'\u673a\u6784\u540d\u79f0',orgHint:'\u4f8b\u5982\uff1a\u8d5b\u5c0f\u8702\u9752\u8bad\u4e2d\u5fc3',createTraining:'\u521b\u5efa\u9752\u8bad\u5de5\u4f5c\u7a7a\u95f4',status:'\u5f53\u524d\u72b6\u6001\uff1a',trainingLockedText:'\u5982\u679c\u4f60\u5df2\u5b8c\u6210\u5f00\u901a\uff0c\u8bf7\u5237\u65b0\uff1b\u8fd8\u6ca1\u6709\u5f00\u901a\u5219\u53ef\u4ee5\u7559\u4e0b\u54a8\u8be2\u7533\u8bf7\u3002',consult:'\u54a8\u8be2\u9752\u8bad\u5f00\u901a',consulted:'\u5df2\u63d0\u4ea4\u54a8\u8be2'
}
const logoSrc = import.meta.env.BASE_URL + 'logo-saixiaofeng.png'
const router = useRouter(),loading = ref(true),state = ref(null),scene = ref('event'),consulted = ref(false),trainingReady = ref(false),submitting = ref(false)
const eventForm = reactive({name:'',city:''}),trainingForm = reactive({name:''})
const reviewOnly = computed(() => Boolean(state.value?.hasBusinessRelation && !state.value?.organization))
const trainingStatus = computed(() => ({active:'\u5df2\u5f00\u901a',enabled:'\u5df2\u5f00\u901a',paid:'\u5df2\u5f00\u901a',trial:'\u8bd5\u7528\u5f00\u901a',inactive:'\u672a\u5f00\u901a'})[String(state.value?.training?.status || 'inactive')] || '\u5f85\u786e\u8ba4')
async function loadState(){loading.value=true;try{const result=await callFunction('onboardingWorkspace',{action:'state'});if(!result?.success)throw new Error(result?.message||result?.error||'state failed');state.value=result;trainingReady.value=Boolean(result.training?.hasBackendProvision&&['active','enabled','paid','trial'].includes(String(result.training?.status||'')));if(result.organization?.id||result.organization?._id){persistOrganization(result.organization);router.replace('/tournament-space')}}catch(error){ElMessage.error(error.message||'state failed')}finally{loading.value=false}}
async function choose(value){scene.value=value;try{await callFunction('onboardingWorkspace',{action:'saveScene',scene:value})}catch{}}
async function createEvent(){if(submitting.value)return;if(eventForm.name.length<2||!eventForm.city)return ElMessage.warning('\u8bf7\u586b\u5199\u8d5b\u4e8b\u540d\u79f0\u548c\u4e3e\u529e\u57ce\u5e02');submitting.value=true;try{const result=await callFunction('onboardingWorkspace',{action:'createEventSpace',name:eventForm.name,city:eventForm.city});if(!result?.success)throw new Error(result?.message||result?.error||'create failed');persistOrganization(result.organization||{id:result.organizationId,name:eventForm.name+'\u4e3b\u529e\u65b9'});router.replace(result.tournament?.id?'/tournaments/'+result.tournament.id:'/tournament-space')}catch(error){ElMessage.error(error.message||'create failed')}finally{submitting.value=false}}
async function createTraining(){if(submitting.value)return;if(trainingForm.name.length<2)return ElMessage.warning('\u8bf7\u586b\u5199\u673a\u6784\u540d\u79f0');submitting.value=true;try{const result=await callFunction('onboardingWorkspace',{action:'createTrainingWorkspace',name:trainingForm.name});if(!result?.success)throw new Error(result?.message||result?.error||'create failed');persistOrganization(result.organization);ElMessage.success('\u9752\u8bad\u5de5\u4f5c\u7a7a\u95f4\u5df2\u521b\u5efa');router.replace('/tournament-space')}catch(error){ElMessage.error(error.message||'create failed')}finally{submitting.value=false}}
async function consult(){if(submitting.value||consulted.value)return;submitting.value=true;try{const result=await callFunction('onboardingWorkspace',{action:'createTrainingConsultation'});if(!result?.success)throw new Error(result?.message||result?.error||'consult failed');consulted.value=true;ElMessage.success('\u54a8\u8be2\u7533\u8bf7\u5df2\u63d0\u4ea4')}catch(error){ElMessage.error(error.message||'consult failed')}finally{submitting.value=false}}
function persistOrganization(organization){if(!organization?.id&&!organization?._id)return;const id=organization.id||organization._id,name=organization.name||organization.organizationName||'';let user={};try{user=JSON.parse(localStorage.getItem('userInfo')||'{}')}catch{}localStorage.setItem('userInfo',JSON.stringify({...user,orgId:id,organizationId:id,organizationName:name}));localStorage.setItem('currentOrganization',JSON.stringify({id,name}))}
async function signOut(){await logout();router.replace('/login')}
onMounted(loadState)
</script>
<style scoped>
.onboard{min-height:100vh;background:linear-gradient(145deg,#f5fbf7,#e8f1eb);color:#183126}.topbar{height:72px;display:flex;align-items:center;justify-content:space-between;padding:0 7vw;background:#fff;border-bottom:1px solid #dce9df}.brand{display:flex;align-items:center;gap:12px;color:#17673e;text-decoration:none}.brand img{width:43px;height:43px}.link,.ghost{border:0;color:#17673e;background:transparent;cursor:pointer}.main{max-width:1100px;margin:auto;padding:74px 28px}.eyebrow{color:#0d9a58;font-weight:800;letter-spacing:1px}.main h1{margin:14px 0;color:#123e2b;font-size:42px}.lead{max-width:720px;color:#5f7167;font-size:17px;line-height:1.7}.choices{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:48px}.choice,.card{padding:27px 30px;border:1px solid #d1e5d7;border-radius:18px;background:#fff;box-shadow:0 10px 28px #23603c10}.choice{min-height:160px;text-align:left;cursor:pointer}.choice.active,.choice:hover{border-color:#25a764}.choice em{display:block;color:#0d9a58;font-style:normal;font-size:13px}.choice strong{display:block;margin:10px 0;color:#153c2a;font-size:26px}.choice span{display:block;color:#667a6d;line-height:1.6}.card{margin-top:24px}.card h2{margin:0 0 10px;color:#183d2b}.card p{color:#64766b;line-height:1.7}.card form{display:grid;grid-template-columns:1fr 1fr auto;gap:16px;align-items:end}.card label{display:flex;flex-direction:column;gap:8px;color:#52655a;font-size:13px}.card input{height:44px;padding:0 13px;border:1px solid #cbded1;border-radius:9px}.primary{height:44px;padding:0 20px;border:0;border-radius:9px;color:#fff;background:#108b4b;font-weight:700;cursor:pointer}.review{text-align:center}.locked{padding:17px;border-radius:12px;background:#fbf8ef;color:#735b2a}.ghost{height:44px;padding:0 15px}@media(max-width:760px){.main{padding:44px 18px}.main h1{font-size:34px}.choices,.card form{grid-template-columns:1fr}}
</style>
